"""Sphinx configuration for pyoxynet.readthedocs.io."""

import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, '..', 'pyoxynet'))   # the package source, for autodoc
sys.path.insert(0, HERE)                                   # oxynet_brand

# Oxynet's palette and fonts. oxynet_brand.py and _static/oxynet-mark.svg are generated by
# harness/registry.py in the orchestration repo from registry/brand.toml: never edit them here.
from oxynet_brand import BRAND, BRAND_ON_LIGHT, FONTS  # noqa: E402

# -- Project -----------------------------------------------------------------

project = 'pyoxynet'
copyright = '2025, Andrea Zignoli'
author = 'Andrea Zignoli'

# The version, from the installed package (Read the Docs installs it) or from pyproject.toml
try:
    from importlib.metadata import version as _installed_version
    release = _installed_version('pyoxynet')
except Exception:
    with open(os.path.join(HERE, '..', 'pyoxynet', 'pyproject.toml')) as _f:
        release = re.search(r'^version = "([^"]+)"', _f.read(), re.M).group(1)
version = release

# -- Extensions --------------------------------------------------------------

extensions = [
    'sphinx.ext.duration',
    'sphinx.ext.doctest',
    'sphinx.ext.autodoc',
    'sphinx.ext.autosummary',
    'sphinx.ext.napoleon',
    'sphinx.ext.viewcode',
]

napoleon_google_docstring = True
napoleon_numpy_docstring = True
napoleon_include_init_with_doc = True

autosummary_generate = True

autodoc_mock_imports = ['tensorflow', 'ai_edge_litert']
autodoc_default_options = {
    'members': True,
    'undoc-members': False,
    'show-inheritance': True,
}

exclude_patterns = ['_build']

# -- HTML: Furo, in Oxynet's palette -------------------------------------------

html_theme = 'furo'
html_title = f'pyoxynet {release}'
html_logo = '_static/oxynet-mark.svg'
html_static_path = ['_static']
html_css_files = [
    'https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700'
    '&family=Geist+Mono:wght@400;500&display=swap',
    'sidebar.css',
]

_fonts = {
    'font-stack': f'"{FONTS["sans"]}", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
    'font-stack--monospace': f'"{FONTS["mono"]}", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace',
}

html_theme_options = {
    'light_css_variables': {
        'color-brand-primary': BRAND_ON_LIGHT['accent'],
        'color-brand-content': BRAND_ON_LIGHT['accent'],
        **_fonts,
    },
    'dark_css_variables': {
        'color-brand-primary': BRAND['accent'],
        'color-brand-content': BRAND['accent'],
        'color-background-primary': BRAND['background'],
        'color-background-secondary': BRAND['surface'],
        'color-background-border': BRAND['border'],
        'color-foreground-primary': BRAND['foreground'],
        'color-foreground-muted': BRAND['muted'],
    },
    'source_repository': 'https://github.com/andreazignoli/pyoxynet/',
    'source_branch': 'master',
    'source_directory': 'docs/',
}
